// Invoices (9 Oct 2026). Reads come straight from public.invoices (RLS: the
// admin tier); every write goes through the client-invoices edge function.

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import type { InvoiceStatus } from "@/lib/invoices/invoiceMaths";

// invoices gained columns in migration 20261009120000 and types.ts is only
// regenerated by the hosted builder on sync, so reads are uncast .from() calls with the
// result typed here (CLAUDE.md: "write an uncast .from('table')").

export const INVOICES_QUERY_KEY = ["client-invoices"];

export interface InvoiceRow {
  id: string;
  client_id: string | null;
  invoice_number: string;
  amount: number;
  status: InvoiceStatus;
  file_path: string | null;
  description: string | null;
  due_date: string | null;
  sent_at: string | null;
  paid_at: string | null;
  created_by: string | null;
  created_at: string;
  issue_date: string | null;
  vat_rate: number;
  vat_amount: number;
  total_amount: number | null;
  bill_to_name: string | null;
  bill_to_address: string | null;
  line_description: string | null;
  recipient_email: string | null;
  sent_to: string | null;
  send_count: number;
  notes: string | null;
  client_profiles: { company_name: string | null; contact_name: string | null; email: string | null; status: string | null } | null;
}

export function useClientInvoices(enabled = true) {
  return useQuery<InvoiceRow[]>({
    queryKey: INVOICES_QUERY_KEY,
    enabled,
    staleTime: 15_000,
    queryFn: async () => {
      const { data, error } = await supabase
        .from("invoices")
        .select("*, client_profiles(company_name, contact_name, email, status)")
        .order("created_at", { ascending: false });
      if (error) throw error;
      return (data ?? []) as unknown as InvoiceRow[];
    },
  });
}

/** Latest invoice per client, for the chips on the onboarding tab. */
export function useLatestInvoiceByClient(clientIds: string[], enabled = true) {
  const key = [...clientIds].sort().join(",");
  return useQuery<Record<string, InvoiceRow>>({
    queryKey: ["client-invoices-by-client", key],
    enabled: enabled && clientIds.length > 0,
    staleTime: 15_000,
    queryFn: async () => {
      const { data, error } = await supabase
        .from("invoices")
        .select("*")
        .in("client_id", clientIds)
        .neq("status", "cancelled")
        .order("created_at", { ascending: false });
      if (error) throw error;
      const out: Record<string, InvoiceRow> = {};
      for (const row of (data ?? []) as unknown as InvoiceRow[]) {
        if (row.client_id && !out[row.client_id]) out[row.client_id] = row;
      }
      return out;
    },
  });
}

export interface InvoiceClientOption {
  id: string;
  company_name: string;
  contact_name: string | null;
  email: string | null;
  status: string | null;
  billing_address: string | null;
}

export function useInvoiceClientOptions(enabled = true) {
  return useQuery<InvoiceClientOption[]>({
    queryKey: ["client-invoices-client-options"],
    enabled,
    staleTime: 30_000,
    queryFn: async () => {
      const { data, error } = await supabase
        .from("client_profiles")
        .select("id, company_name, contact_name, email, status, billing_address, is_test_account" as "id")
        .in("status", ["active", "pending"])
        .order("company_name");
      if (error) throw error;
      return ((data ?? []) as unknown as Array<InvoiceClientOption & { is_test_account: boolean | null }>)
        .filter((c) => c.is_test_account !== true)
        .map(({ is_test_account: _t, ...c }) => c);
    },
  });
}

export interface InvoiceFormPayload {
  client_profile_id?: string | null;
  create_client?: boolean;
  bill_to_name: string;
  bill_to_address: string;
  recipient_email: string;
  issue_date: string;
  due_date: string;
  amount: number;
  vat_rate: number;
  line_description: string;
  notes?: string;
}

async function invoke(body: Record<string, unknown>) {
  const { data, error } = await supabase.functions.invoke("client-invoices", { body });
  if (error) {
    const ctx = (error as { context?: Response }).context;
    if (ctx && typeof ctx.json === "function") {
      const payload = await ctx.json().catch(() => null);
      if (payload?.error) throw new Error(payload.error);
    }
    throw new Error(error.message || "Something went wrong");
  }
  if (data?.error) throw new Error(data.error);
  return data;
}

export function useInvoiceAction() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (input: { action: string } & Record<string, unknown>) => invoke(input),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: INVOICES_QUERY_KEY });
      qc.invalidateQueries({ queryKey: ["client-invoices-by-client"] });
      qc.invalidateQueries({ queryKey: ["client-invoices-client-options"] });
      qc.invalidateQueries({ queryKey: ["client-onboarding-journeys"] });
    },
  });
}

export async function previewInvoicePdf(form: InvoiceFormPayload): Promise<{ invoice_number: string; filename: string; pdf_base64: string }> {
  return invoke({ action: "preview", ...form });
}

/**
 * Show a base64 PDF. Pass a tab opened synchronously in the click handler
 * (`window.open("about:blank")`) so popup blockers let it through; without
 * one it falls back to opening a new tab here.
 */
export function openPdfBase64(b64: string, tab?: Window | null) {
  const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  const url = URL.createObjectURL(new Blob([bytes], { type: "application/pdf" }));
  if (tab) tab.location.href = url; else window.open(url, "_blank", "noopener");
  setTimeout(() => URL.revokeObjectURL(url), 60_000);
}
